/**
 * The offline app shell (D-048). Generated by `scripts/build-sw.mjs` — edit the
 * template, never `dist/sw.js`.
 *
 * Two rules, both load-bearing rather than stylistic:
 *
 * **Network-first, always** (D-054). The cache exists so the app *opens* with
 * no network — vision criterion 5 — not so it can serve yesterday's shell to
 * someone online. A cached response only ever answers a request the network
 * refused. This is also what makes the SW incapable of reintroducing the
 * staleness D-054 exists to prevent: a fixed MIME type or a corrected header
 * reaches the user on their next load, not whenever the cache happens to expire.
 *
 * **`/data/` is never touched.** Not "not precached" — not handled at all. The
 * manifest is the freshness signal (D-042), the chunks are immutable and become
 * OPFS-resident once imported, and a cache in front of either could serve a
 * stale manifest and break the staleness indicator, which is the one guard
 * vision criterion 7 has against confident-but-old counts. The check is on the
 * *path*, before anything else, so no later branch can reach a `/data/` URL.
 *
 * Model weights (M8) stay out for the same reason plus one more: they live in
 * OPFS under the app's own management (D-045), and multi-gigabyte cache entries
 * are the wrong tool.
 */

const VERSION = '__CACHE_VERSION__'
const CACHE = `cve-shell-${VERSION}`
const PRECACHE = __PRECACHE__

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE)
      // `reload` so installing a new worker cannot populate its cache from the
      // HTTP cache that the deploy just invalidated — the failure D-054 fixed
      // at the server would otherwise be re-imported here.
      //
      // **Failures are not swallowed.** `activate` deletes the previous cache,
      // which is by then the only complete one, so an install that quietly
      // stored nine files out of twenty-eight would replace a working offline
      // shell with a broken one — and the symptom arrives weeks later with no
      // network to diagnose it on. A rejected `install` leaves the *old* worker
      // controlling and its cache intact, which is the honest outcome: no new
      // shell rather than a shell that cannot boot.
      const results = await Promise.allSettled(
        PRECACHE.map((url) => cache.add(new Request(url, { cache: 'reload' })))
      )
      const missed = results.filter((entry) => entry.status === 'rejected').length
      if (missed) {
        throw new Error(`offline shell: ${missed} of ${PRECACHE.length} files could not be cached`)
      }
      // Activate immediately rather than waiting for every tab to close, and
      // claim the open ones below. D-048's update rule is that a deploy cannot
      // leave a stale shell talking to a new data plane for longer than one
      // session, and "waiting" is how a shell survives for weeks in a tab
      // nobody closes. It is safe *because* the strategy is network-first: a
      // claimed page's next fetch still goes to the network, so a new worker
      // taking over an old page changes nothing it would not already have got.
      await self.skipWaiting()
    })()
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const name of await caches.keys()) {
        if (name.startsWith('cve-shell-') && name !== CACHE) await caches.delete(name)
      }
      await self.clients.claim()
    })()
  )
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return

  let url
  try {
    url = new URL(request.url)
  } catch {
    return
  }

  // Structural, and first: the data plane passes through untouched, and so does
  // anything not on this origin. `respondWith` is never called for either, so
  // the browser handles them exactly as it would with no worker installed.
  if (url.origin !== self.location.origin) return
  if (url.pathname === '/data' || url.pathname.startsWith('/data/')) return

  event.respondWith(
    (async () => {
      try {
        const response = await fetch(request)
        // Only successful, non-opaque responses replace what is cached. A 404
        // or a 502 cached over a good shell file is an outage that survives the
        // outage — which is what happened at the origin with `immutable` on
        // error responses (M5's Cloudflare flip) and is worth not repeating here.
        if (response && response.ok && response.type === 'basic') {
          const copy = response.clone()
          const cache = await caches.open(CACHE)
          await cache.put(request, copy).catch(() => undefined)
        }
        return response
      } catch (error) {
        // Exact match first. `ignoreSearch` would answer one URL with another's
        // bytes whenever two requests differ only by query — and this app makes
        // exactly that pair: `/sqlite/sqlite3-opfs-async-proxy.js?vfs=opfs` and
        // `?vfs=opfs-wl`.
        const cached = await caches.match(request)
        if (cached) return reissue(cached)
        // Then ignoring the query. SQLite loads its own async proxy as
        // `sqlite3-opfs-async-proxy.js?vfs=opfs` and `?vfs=opfs-wl` — one file,
        // labelled twice — and neither spelling is knowable at build time, so
        // the precached bare URL is the only entry that can answer them.
        const loose = await caches.match(request, { ignoreSearch: true })
        if (loose) return reissue(loose)
        // A navigation with no network and no match at all still has to open
        // the app: `/`, `/?schema=3`, a permalink with a fragment — all of them
        // are the same document. Falling back to it is what makes a *reopen*
        // work rather than only a still-open tab.
        if (request.mode === 'navigate') {
          const shell = await caches.match('/')
          if (shell) return reissue(shell)
        }
        throw error
      }
    })()
  )
})

/**
 * Hand back a cached response as a *fresh* one.
 *
 * This is not tidiness. A `Response` read out of a `Cache` carries the URL it
 * was stored under, and the browser uses a script response's URL as the
 * resulting worker's own `location` — which drops the fragment the request
 * carried. Turbopack puts the database worker's entire chunk list in that
 * fragment (`#params=…`), so serving the worker script from the cache made it
 * throw **"Missing worker bootstrap config"**: the app opened offline, rendered,
 * and then sat forever with no database and — until `worker.onerror` was
 * wired up — nothing on screen.
 *
 * Re-wrapping the body produces a response with no URL of its own, so the
 * worker keeps the URL it was actually constructed with, fragment included.
 * Online this never bit, because the network path returns `fetch`'s own
 * response; it appeared only when the cache was the one answering.
 */
function reissue(cached) {
  return new Response(cached.body, {
    status: cached.status,
    statusText: cached.statusText,
    headers: cached.headers,
  })
}

// The version, for the diagnostics panel (D-009): a broken or stale worker is
// invisible by design, and there is no telemetry to notice it for us.
self.addEventListener('message', (event) => {
  if (event.data === 'version') event.source?.postMessage({ type: 'sw-version', version: VERSION })
})
